"""One static industrial foundry-style staging court, one scene and zero new independent models. Two complete qualified original models retain unit scale, every original raw GLB buffer, material dictionary and internal node hierarchy under translation-only wrappers: the whole tall ported cupola stands at the rear-right, while the whole empty trunnion-bail ladle stands separately on the lower forward-right apron. New scene-only architecture forms a grounded slab, a left stair rising to a high landing and short transverse raised deck beside the upper shaft opening, with full supporting columns and two fixed outer rail appearances. The entire side sill, lower spout, shaft feet and ladle remain intact and separate from the architecture; the high deck terminates with an explicit small gap, not a claimed compatible connection. The low ladle is staged away from the low port and is not shown receiving material. Unlike the old kiln containing one vessel on its own shelf or the flat steam piston/table/rack corner, this composition separates a high approach level from the independent lower vessel bay and an open under-deck region. No old mesh is extracted, resized, recoloured or counted again. No metal, fuel, fire, pouring, furnace process, vessel capacity, suspension, machinery motion, operator access, usable stair dimensions, fall protection, heat separation, load, construction, installation or safety capability. Rigging animation and interaction not made or verified."""
import base64, copy, hashlib, json, math, struct, zlib
from pathlib import Path
ASSET = 'industrial-whole-high-shaft-and-ladle-two-level-staging-court-scene-01'
TITLE = 'Whole High Shaft and Ladle Two Level Staging Court'
TOL = 2e-07
INPUTS = {'cupola': {'bytes': 176300, 'sha256': '0afa1e46d6ea42cb73ba1052c2df11f3428f868da3b19205d9078199549cac7c', 'compressed': ''}, 'ladle': {'bytes': 99192, 'sha256': '135a59724a8ccc03d70df925c07cada1fce911e2a81c8fea27209e6e80cffaad', 'compressed': ''}}
SOURCE_INPUTS = {'cupola': {'bytes': 27637, 'sha256': '17c6d9b04a56af84ed2338f3cb3767a541f57deb2f9d8f6472c52b254c6b553f', 'compressed': ''}, 'ladle': {'bytes': 26443, 'sha256': '3bd2f3d1ce2da4228496dd7f4b54c52cecccf3e2c6837bb1e7f46f6bc8b96c6b', 'compressed': ''}}
PALETTE = [('SceneOnlyApron', (0.27, 0.29, 0.28, 1), 0.92), ('SceneOnlyRaisedStoneLanding', (0.44, 0.39, 0.3, 1), 0.91), ('SceneOnlyFixedOuterRails', (0.12, 0.15, 0.16, 1), 0.7)]
G = {}

def record(name, v, fs, m):
    ts = []
    mats = []
    for i, f in enumerate(fs):
        for k in range(1, len(f) - 1):
            ts.append((f[0], f[k], f[k + 1]))
            mats.append(m[i] if isinstance(m, list) else m)
    vol = sum((sum((v[a][i] * [v[b][1] * v[c][2] - v[b][2] * v[c][1], v[b][2] * v[c][0] - v[b][0] * v[c][2], v[b][0] * v[c][1] - v[b][1] * v[c][0]][i] for i in range(3))) for a, b, c in ts)) / 6
    if vol < 0:
        ts = [(a, c, b) for a, b, c in ts]
    assert abs(vol) > 1e-12
    G[name] = (v, ts, mats)

def rect(x, y0, y1, r):
    return [(-x + r, y0), (x - r, y0), (x, y0 + r), (x, y1 - r), (x - r, y1), (-x + r, y1), (-x, y1 - r), (-x, y0 + r)]

def prism(name, p, z0, z1, m, transform=None):
    v = [(x, y, z) for z in [z0, z1] for x, y in p]
    n = len(p)
    f = [tuple(reversed(range(n))), tuple(range(n, 2 * n))] + [(i, (i + 1) % n, (i + 1) % n + n, i + n) for i in range(n)]
    if transform:
        v = [transform(q) for q in v]
    record(name, v, f, m)

def box(name, lo, hi, m, transform=None):
    prism(name, [(lo[0], lo[1]), (hi[0], lo[1]), (hi[0], hi[1]), (lo[0], hi[1])], lo[2], hi[2], m, transform)

def union_boxes(name, boxes, m):
    xs = sorted(set((p[0] for b in boxes for p in b)))
    ys = sorted(set((p[1] for b in boxes for p in b)))
    zs = sorted(set((p[2] for b in boxes for p in b)))
    faces = {}
    for i in range(len(xs) - 1):
        for j in range(len(ys) - 1):
            for k in range(len(zs) - 1):
                c = ((xs[i] + xs[i + 1]) / 2, (ys[j] + ys[j + 1]) / 2, (zs[k] + zs[k + 1]) / 2)
                if not any((all((lo[t] < c[t] < hi[t] for t in range(3))) for lo, hi in boxes)):
                    continue
                v = [(x, y, z) for z in [zs[k], zs[k + 1]] for y in [ys[j], ys[j + 1]] for x in [xs[i], xs[i + 1]]]
                for f in [(0, 2, 3, 1), (4, 5, 7, 6), (0, 1, 5, 4), (2, 6, 7, 3), (0, 4, 6, 2), (1, 3, 7, 5)]:
                    q = tuple((v[t] for t in f))
                    key = tuple(sorted(q))
                    if key in faces:
                        del faces[key]
                    else:
                        faces[key] = q
    verts = []
    ix = {}
    fs = []
    for q in faces.values():
        f = []
        for p in q:
            if p not in ix:
                ix[p] = len(verts)
                verts.append(p)
            f.append(ix[p])
        fs.append(f)
    record(name, verts, fs, m)

def cyl(name, center, r, length, axis, m, n=12):
    axes = [i for i in range(3) if i != axis]
    v = []
    for end in [-0.5, 0.5]:
        for i in range(n):
            p = list(center)
            p[axis] += end * length
            p[axes[0]] += r * math.cos(i * math.tau / n)
            p[axes[1]] += r * math.sin(i * math.tau / n)
            v.append(tuple(p))
    record(name, v, [tuple(reversed(range(n))), tuple(range(n, 2 * n))] + [(i, (i + 1) % n, (i + 1) % n + n, i + n) for i in range(n)], m)

def sweep(name, path, r, m, n=12):
    v = []
    for j, p in enumerate(path):
        a = path[max(0, j - 1)]
        b = path[min(len(path) - 1, j + 1)]
        dy = b[1] - a[1]
        dz = b[2] - a[2]
        q = math.hypot(dy, dz)
        u = (0, dz / q, -dy / q)
        for i in range(n):
            t = math.tau * i / n
            v.append((p[0] + r * math.cos(t), p[1] + u[1] * r * math.sin(t), p[2] + u[2] * r * math.sin(t)))
    fs = [tuple(reversed(range(n))), tuple(((len(path) - 1) * n + i for i in range(n)))]
    fs += [(k * n + i, k * n + (i + 1) % n, (k + 1) * n + (i + 1) % n, (k + 1) * n + i) for k in range(len(path) - 1) for i in range(n)]
    record(name, v, fs, m)

def ring(name, x0, x1, y, th, z0, z1, m, tr=None):
    outer = [(x0, -y), (x1, -y), (x1, y), (x0, y)]
    inner = [(x0 + th, -y + th), (x1 - th, -y + th), (x1 - th, y - th), (x0 + th, y - th)]
    v = [(x, y, z) for z, p in [(z0, outer), (z0, inner), (z1, outer), (z1, inner)] for x, y in p]
    fs = []
    for i in range(4):
        j = (i + 1) % 4
        fs += [(i, j, 4 + j, 4 + i), (8 + i, 12 + i, 12 + j, 8 + j), (i, 8 + i, 8 + j, j), (4 + i, 4 + j, 12 + j, 12 + i)]
    if tr:
        v = [tr(p) for p in v]
    record(name, v, fs, m)

def rod(name, a, b, r, m, n=8):
    d = [b[i] - a[i] for i in range(3)]
    le = math.sqrt(sum((t * t for t in d)))
    w = [t / le for t in d]
    seed = [0, 0, 1] if abs(w[2]) < 0.9 else [0, 1, 0]
    u = [w[1] * seed[2] - w[2] * seed[1], w[2] * seed[0] - w[0] * seed[2], w[0] * seed[1] - w[1] * seed[0]]
    le = math.sqrt(sum((t * t for t in u)))
    u = [t / le for t in u]
    v = [w[1] * u[2] - w[2] * u[1], w[2] * u[0] - w[0] * u[2], w[0] * u[1] - w[1] * u[0]]
    vs = [tuple((p[k] + r * (u[k] * math.cos(math.tau * i / n) + v[k] * math.sin(math.tau * i / n)) for k in range(3))) for p in [a, b] for i in range(n)]
    record(name, vs, [tuple(reversed(range(n))), tuple(range(n, 2 * n))] + [(i, (i + 1) % n, (i + 1) % n + n, i + n) for i in range(n)], m)

def earclip(poly):
    ids = list(range(len(poly)))
    out = []

    def cross2(a, b, c):
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
    while len(ids) > 3:
        done = False
        for k, i in enumerate(ids):
            a, b, c = (ids[k - 1], i, ids[(k + 1) % len(ids)])
            if cross2(poly[a], poly[b], poly[c]) <= 1e-13:
                continue
            if any((j not in [a, b, c] and min(cross2(poly[a], poly[b], poly[j]), cross2(poly[b], poly[c], poly[j]), cross2(poly[c], poly[a], poly[j])) >= -1e-13 for j in ids)):
                continue
            out.append((a, b, c))
            ids.pop(k)
            done = True
            break
        assert done, 'Cannot triangulate complete outer shell'
    out.append(tuple(ids))
    return out

def annular_x(name, x, z, ri, ro, th, m, n=32):
    vs = [(xx, r * math.cos(i * math.tau / n), z + r * math.sin(i * math.tau / n)) for xx, r in [(x - th / 2, ri), (x - th / 2, ro), (x + th / 2, ro), (x + th / 2, ri)] for i in range(n)]
    fs = [(j * n + i, j * n + (i + 1) % n, (j + 1) % 4 * n + (i + 1) % n, (j + 1) % 4 * n + i) for j in range(4) for i in range(n)]
    record(name, vs, fs, m)

def axial_profile(name, profile, center, axis, m, n=32):
    axes = [i for i in range(3) if i != axis]
    vs = []
    rings = []
    for r, z in profile:
        row = []
        for j in range(1 if r == 0 else n):
            p = list(center)
            p[axis] += z
            p[axes[0]] += r * math.cos(j * math.tau / n)
            p[axes[1]] += r * math.sin(j * math.tau / n)
            row.append(len(vs))
            vs.append(tuple(p))
        rings.append(row)
    fs = []
    for k, row in enumerate(rings):
        nex = rings[(k + 1) % len(rings)]
        if len(row) == len(nex) == 1:
            continue
        for j in range(n):
            jj = (j + 1) % n
            if len(row) == 1:
                fs.append((row[0], nex[j], nex[jj]))
            elif len(nex) == 1:
                fs.append((row[j], nex[0], row[jj]))
            else:
                fs.append((row[j], nex[j], nex[jj], row[jj]))
    record(name, vs, fs, m)

def make_geometry():
    G.clear()
    box('SceneOnlyFoundryCourtFloor', (-4.4, -4.8, 0), (4.4, 4.8, 0.12), 0)
    b = []
    for i in range(18):
        b.append(((-3.5, -4.4 + i * 0.2, 0.1), (-1.7, -4.2 + i * 0.2, 0.12 + (i + 1) * 0.15)))
    b.extend([((-3.5, -0.8, 2.64), (-1.7, 1.0, 2.82)), ((-1.7, -0.8, 2.64), (1.25, -0.24, 2.82))])
    for x, y in [(-3.3, 0.78), (-1.9, 0.78), (-1.5, -0.52), (0.95, -0.52)]:
        b.append(((x - 0.1, y - 0.1, 0.1), (x + 0.1, y + 0.1, 2.7)))
    union_boxes('SceneOnlyFoundryCourtRaisedStairAndLanding', [tuple(tuple(round(c, 6) for c in point) for point in pair) for pair in b], 1)
    b = [((-3.48, -0.76, 3.52), (-3.4, 0.97, 3.59)), ((-3.48, 0.89, 3.52), (-1.72, 0.97, 3.59))]
    for x, y in [(-3.44, -0.7), (-3.44, 0.93), (-1.76, 0.93)]:
        b.append(((x - 0.035, y - 0.035, 2.77), (x + 0.035, y + 0.035, 3.55)))
    union_boxes('SceneOnlyFoundryCourtOuterLandingRail', b, 2)
    b = [((-1.65, -0.78, 3.52), (1.2, -0.71, 3.59))]
    for x in [-1.6, -0.2, 1.15]:
        b.append(((x - 0.035, -0.78, 2.77), (x + 0.035, -0.71, 3.55)))
    union_boxes('SceneOnlyFoundryCourtOuterCrossRail', b, 2)
    return G

def pack_glb(doc, blob):
    j = json.dumps(doc, separators=(',', ':'), allow_nan=False).encode()
    j += b' ' * (-len(j) % 4)
    b = bytes(blob) + b'\x00' * (-len(blob) % 4)
    return struct.pack('<4sII', b'glTF', 2, 12 + 8 + len(j) + 8 + len(b)) + struct.pack('<II', len(j), 1313821514) + j + struct.pack('<II', len(b), 5130562) + b

def compose_floor(inputs):
    make_geometry()
    d = dict(asset={'version': '2.0', 'generator': 'Original static mesh construction'}, scene=0, scenes=[{'name': TITLE, 'nodes': [0]}], nodes=[{'name': 'AssetRoot__' + ASSET, 'children': []}], meshes=[], materials=[{'name': n, 'doubleSided': True, 'pbrMetallicRoughness': {'baseColorFactor': c, 'metallicFactor': 0.0, 'roughnessFactor': r}} for n, c, r in PALETTE], accessors=[], bufferViews=[], buffers=[])
    blob = bytearray()

    def array(values, component, kind):
        flat = [v for row in values for v in row] if kind == 'VEC3' else values
        fmt = 'f' if component == 5126 else 'I'
        raw = struct.pack('<' + fmt * len(flat), *flat)
        offset = len(blob)
        blob.extend(raw)
        blob.extend(b'\x00' * (-len(blob) % 4))
        view = len(d['bufferViews'])
        d['bufferViews'].append({'buffer': 0, 'byteOffset': offset, 'byteLength': len(raw)})
        a = {'bufferView': view, 'componentType': component, 'count': len(values), 'type': kind}
        if kind == 'VEC3':
            a.update(min=[min((p[k] for p in values)) for k in range(3)], max=[max((p[k] for p in values)) for k in range(3)])
        index = len(d['accessors'])
        d['accessors'].append(a)
        return index
    for name, (v, fs, mats) in G.items():
        prim = []
        for mat in sorted(set(mats)):
            positions = []
            normals = []
            for ids, mi in zip(fs, mats):
                if mi != mat:
                    continue
                a, b, c = [v[i] for i in ids]
                u = [b[k] - a[k] for k in range(3)]
                w = [c[k] - a[k] for k in range(3)]
                n = (u[1] * w[2] - u[2] * w[1], u[2] * w[0] - u[0] * w[2], u[0] * w[1] - u[1] * w[0])
                le = math.sqrt(sum((x * x for x in n)))
                assert le > 1e-12
                n = [x / le for x in n]
                positions.extend(((x, z, -y) for x, y, z in [a, b, c]))
                normals.extend([(n[0], n[2], -n[1])] * 3)
            prim.append({'attributes': {'POSITION': array(positions, 5126, 'VEC3'), 'NORMAL': array(normals, 5126, 'VEC3')}, 'indices': array(list(range(len(positions))), 5125, 'SCALAR'), 'material': mat, 'mode': 4})
        mesh = len(d['meshes'])
        d['meshes'].append({'name': name, 'primitives': prim})
        node = len(d['nodes'])
        d['nodes'].append({'name': name, 'mesh': mesh})
        d['nodes'][0]['children'].append(node)
    d['buffers'] = [{'byteLength': len(blob)}]
    return (d, bytes(blob), {'new_original_geometry': True, 'triangles': sum((len(f) for v, f, m in G.values())), 'mesh_count': len(G), 'whole_original_model_count': 0, 'static_pose_only': True})
PLACEMENTS = [('cupola', (1.0, 1.0, 0.12)), ('ladle', (2.35, -2.4, 0.12))]

def decode_document(raw):
    assert raw[:4] == b'glTF'
    p = 12
    d = None
    b = None
    while p < len(raw):
        n, k = struct.unpack_from('<II', raw, p)
        chunk = raw[p + 8:p + 8 + n]
        p += 8 + n
        if k == 1313821514:
            d = json.loads(chunk)
        elif k == 5130562:
            b = chunk
    assert d is not None and b is not None
    return (d, b)

def compose(inputs):
    d = dict(asset={'version': '2.0', 'generator': 'Complete original GLB payloads with rigid whole-instance parent wrappers'}, scene=0, scenes=[{'name': TITLE, 'nodes': [0]}], nodes=[{'name': 'WholeFoundryStagingCourt', 'children': []}], materials=[], meshes=[], accessors=[], bufferViews=[], buffers=[])
    blob = bytearray()

    def append(doc, data, label, t):
        assert len(doc['buffers']) == 1 and (not any((doc.get(x) for x in ['skins', 'animations', 'textures', 'images'])))
        assert len(data) >= doc['buffers'][0]['byteLength']
        no, mo, ma, ac, bv = (len(d['nodes']), len(d['meshes']), len(d['materials']), len(d['accessors']), len(d['bufferViews']))
        offset = len(blob)
        blob.extend(data[:doc['buffers'][0]['byteLength']])
        blob.extend(b'\x00' * (-len(blob) % 4))
        d['materials'].extend(copy.deepcopy(doc['materials']))
        for v in doc['bufferViews']:
            v = copy.deepcopy(v)
            assert v.get('buffer', 0) == 0
            v['buffer'] = 0
            v['byteOffset'] = v.get('byteOffset', 0) + offset
            d['bufferViews'].append(v)
        for v in doc['accessors']:
            v = copy.deepcopy(v)
            assert 'sparse' not in v
            v['bufferView'] += bv
            d['accessors'].append(v)
        for m in doc['meshes']:
            m = copy.deepcopy(m)
            for p in m['primitives']:
                assert not p.get('targets')
                p['attributes'] = {k: v + ac for k, v in p['attributes'].items()}
                p['indices'] += ac
                p['material'] += ma
            d['meshes'].append(m)
        for n in doc['nodes']:
            n = copy.deepcopy(n)
            if label != 'SceneOnlyFoundryCourtGeometry':
                n.setdefault('extras', {})['whole_original_node_name'] = n.get('name', '')
                n['name'] = label + '__' + n.get('name', '')
            if 'mesh' in n:
                n['mesh'] += mo
            if 'children' in n:
                n['children'] = [i + no for i in n['children']]
            d['nodes'].append(n)
        root = len(d['nodes'])
        d['nodes'].append(dict(name='WholeInstance_' + label, translation=[t[0], t[2], -t[1]], children=[no + i for i in doc['scenes'][doc.get('scene', 0)]['nodes']], extras={'unit_scale': True, 'whole_original_payload': True, 'translation_only_wrapper': True}))
        d['nodes'][0]['children'].append(root)
    for label, t in PLACEMENTS:
        v = INPUTS[label]
        raw = zlib.decompress(base64.b64decode(v['compressed']))
        assert len(raw) == v['bytes'] and hashlib.sha256(raw).hexdigest() == v['sha256']
        doc, data = decode_document(raw)
        append(doc, data, label, t)
    floor, data, proof = compose_floor({})
    append(floor, data, 'SceneOnlyFoundryCourtGeometry', (0, 0, 0))
    d['buffers'] = [{'byteLength': len(blob)}]
    return (d, bytes(blob), dict(new_original_geometry=False, triangles=8072, mesh_count=35, whole_original_model_count=0, scene_count=1, complete_existing_instances=2, static_pose_only=True, original_payloads={k: {a: v[a] for a in ['bytes', 'sha256']} for k, v in INPUTS.items()}, rigid_placements=PLACEMENTS, quarterturn_z_labels=[]))

def main():
    import bpy, sys, time
    from mathutils import Vector
    OUT = Path(__file__).resolve().parent
    inputs = {k: zlib.decompress(base64.b64decode(v['compressed'])) for k, v in INPUTS.items()}
    for k, raw in inputs.items():
        assert hashlib.sha256(raw).hexdigest() == INPUTS[k]['sha256']
    for v in SOURCE_INPUTS.values():
        assert hashlib.sha256(zlib.decompress(base64.b64decode(v['compressed']))).hexdigest() == v['sha256']
    document, blob, proof = compose(inputs)
    model = pack_glb(document, blob)
    (OUT / 'model.glb').write_bytes(model)
    bpy.ops.object.select_all(action='SELECT')
    bpy.ops.object.delete(use_global=False)
    bpy.ops.import_scene.gltf(filepath=str(OUT / 'model.glb'))
    parts = [o for o in bpy.context.scene.objects if o.type == 'MESH']
    assert len(parts) == 35
    triangle_count = sum((len(p.vertices) - 2 for o in parts for p in o.data.polygons))
    assert triangle_count == proof['triangles']
    points = [o.matrix_world @ v.co for o in parts for v in o.data.vertices]
    lo = [min((v[k] for v in points)) for k in range(3)]
    hi = [max((v[k] for v in points)) for k in range(3)]
    assert abs(lo[2]) <= TOL and abs(lo[0] + hi[0]) <= TOL and (abs(lo[1] + hi[1]) <= TOL)
    assert len({m for o in parts for m in o.data.materials}) == 11
    scene = bpy.context.scene
    scene.render.engine = 'CYCLES'
    scene.cycles.samples = 128
    scene.cycles.use_adaptive_sampling = False
    scene.cycles.use_denoising = False
    for layer in scene.view_layers:
        layer.cycles.use_denoising = False
    scene.use_nodes = False
    scene.render.use_compositing = False
    scene.render.threads_mode = 'FIXED'
    scene.render.threads = 4
    scene.render.resolution_x = scene.render.resolution_y = 640
    scene.render.resolution_percentage = 100
    scene.world = scene.world or bpy.data.worlds.new('Neutral instrument preview')
    scene.world.use_nodes = True
    scene.world.node_tree.nodes['Background'].inputs['Color'].default_value = (0.3, 0.3, 0.3, 1)
    scene.world.node_tree.nodes['Background'].inputs['Strength'].default_value = 0.8
    scene.view_settings.view_transform = 'AgX'
    focus = Vector((0.0, 0.0, 1.8))

    def aim(o, pos):
        o.location = pos
        o.rotation_euler = (focus - o.location).to_track_quat('-Z', 'Y').to_euler()
    for name, pos, power, size in [('Key', (-12, -15, 20), 3200, 12), ('Fill', (14, -9, 15), 2200, 10), ('Rim', (6, 15, 18), 2800, 10)]:
        bpy.ops.object.light_add(type='AREA', location=pos)
        o = bpy.context.object
        o.name = 'Preview_' + name
        o.data.energy = power
        o.data.shape = 'DISK'
        o.data.size = size
        aim(o, pos)
    bpy.ops.object.camera_add()
    cam = bpy.context.object
    cam.name = 'Preview_Camera'
    cam.data.type = 'ORTHO'
    scene.camera = cam
    aim(cam, (11, -14, 10))
    bpy.context.view_layer.update()
    rot = cam.rotation_euler.to_quaternion()
    right = rot @ Vector((1, 0, 0))
    up = rot @ Vector((0, 1, 0))
    xx = [v.dot(right) for v in points]
    yy = [v.dot(up) for v in points]
    cam.location += right * ((min(xx) + max(xx)) / 2 - cam.location.dot(right)) + up * ((min(yy) + max(yy)) / 2 - cam.location.dot(up))
    cam.data.ortho_scale = max(max(xx) - min(xx), max(yy) - min(yy)) * 1.12
    bpy.ops.mesh.primitive_plane_add(size=200, location=(0, 0, -0.0003))
    ground = bpy.context.object
    ground.name = 'Preview_ground_not_asset'
    mat = bpy.data.materials.new('Preview_slate')
    mat.diffuse_color = (0.2, 0.24, 0.25, 1)
    ground.data.materials.append(mat)
    bpy.ops.wm.save_as_mainfile(filepath=str(OUT / 'source.blend'), compress=False)

    def config():
        return dict(engine=scene.render.engine, samples=scene.cycles.samples, adaptive=scene.cycles.use_adaptive_sampling, cycles_denoise=scene.cycles.use_denoising, view_layer_denoise=[x.cycles.use_denoising for x in scene.view_layers], compositor_nodes=scene.use_nodes, compositing=scene.render.use_compositing, threads_mode=scene.render.threads_mode, threads=scene.render.threads)
    qa = {'review_mode': 'SELF_REVIEW', 'status': 'GEOMETRY_CREATED_NEEDS_MAKER_REVIEW', 'asset_id': ASSET, 'asset': ASSET, 'source_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(), 'glb_sha256': hashlib.sha256(model).hexdigest(), 'mesh_count': 35, 'mesh_objects': 35, 'triangles': triangle_count, 'materials': 11, 'bounds_min_m': lo, 'bounds_max_m': hi, 'composition': proof, 'native_readback_claim': False, 'normal_setter_or_vertex_bake_used': False, 'render_configuration': {'samples': 128, 'threads': 4, 'engine': 'CYCLES', 'denoising': False}}
    qa['native_saved_render_config'] = config()
    qa['render_configs'] = {}
    if '--geometry-only' not in sys.argv:
        view = sys.argv[sys.argv.index('--tier-single-view') + 1] if '--tier-single-view' in sys.argv else 'thumbnail'
        assert view in ['qa-front', 'thumbnail']
        scene.cycles.samples = 16 if view == 'qa-front' else 128
        qa['render_configs'][view] = config()
        scene.render.filepath = str(OUT / (view + '.png'))
        start = time.monotonic()
        bpy.ops.render.render(write_still=True)
        qa['render'] = {'view': view, 'samples': scene.cycles.samples, 'seconds': time.monotonic() - start, 'original_pixels_reviewed': False}
    (OUT / 'qa-report.json').write_text(json.dumps(qa, indent=2) + '\n')
    files = {}
    for role, name in [('glb', 'model.glb'), ('blend', 'source.blend'), ('generator', 'generate.py'), ('render', 'thumbnail.png')]:
        p = OUT / name
        if p.exists():
            files[role] = {'path': f'assets/industrial/{ASSET}/v1.0.0/{name}', 'size': p.stat().st_size, 'sha256': hashlib.sha256(p.read_bytes()).hexdigest()}
    if len(files) == 4:
        meta = {'id': ASSET, 'version': '1.0.0', 'category': 'scenes', 'assetKind': 'scene', 'theme': 'industrial', 'style': 'source-preserved-low-poly', 'title': TITLE, 'description': 'One static industrial foundry-style staging court, one scene and zero new independent models. Two complete qualified original models retain unit scale, every original raw GLB buffer, material dictionary and internal node hierarchy under translation-only wrappers: the whole tall ported cupola stands at the rear-right, while the whole empty trunnion-bail ladle stands separately on the lower forward-right apron. New scene-only architecture forms a grounded slab, a left stair rising to a high landing and short transverse raised deck beside the upper shaft opening, with full supporting columns and two fixed outer rail appearances. The entire side sill, lower spout, shaft feet and ladle remain intact and separate from the architecture; the high deck terminates with an explicit small gap, not a claimed compatible connection. The low ladle is staged away from the low port and is not shown receiving material. Unlike the old kiln containing one vessel on its own shelf or the flat steam piston/table/rack corner, this composition separates a high approach level from the independent lower vessel bay and an open under-deck region. No old mesh is extracted, resized, recoloured or counted again. No metal, fuel, fire, pouring, furnace process, vessel capacity, suspension, machinery motion, operator access, usable stair dimensions, fall protection, heat separation, load, construction, installation or safety capability. Rigging animation and interaction not made or verified.', 'bounds': dict(zip(['x', 'y', 'z'], [hi[k] - lo[k] for k in range(3)]), unit='m'), 'triangles': triangle_count, 'materials': 11, 'files': files, 'status': 'review', 'license': 'All rights reserved'}
        (OUT / 'metadata.json').write_text(json.dumps(meta, indent=2) + '\n')
    print('SCENE_STAGE_COMPLETE', ASSET, triangle_count)
if __name__ == '__main__':
    main()
